    if (focus?.code==='SESSION_MEMORY') title=T('İlerleme kaydını kontrol et');
    else if (focus?.code==='RUNTIME_INTEGRITY') title=field(report,'RUNTIME_INTEGRITY')?.evidence?.configurationErrors?T('Dosya kontrolünün sürüm bilgisi geçersiz'):T('Bir dosya sürümle uyuşmuyor');
    else if(focus?.status==='FAIL') title=T('İlgilenilmesi gereken bir sorun var');
    const message=focus?.detail||(!tested?T('Uygulamanın mevcut durumunu kontrol edelim.'):T('Yapılan ölçümlerde bir hata bulunmadı. Gözlem bilgisi, başarılı cihaz denemesi değildir.'));
    const advice=focus?.advice||(!tested?T('Hızlı kontrolü çalıştır. Sesin, sayacın ve tempo ayarın değiştirilmez.'):T('Duyulan ses ve ekran kilidi davranışını cihazında ayrıca dene. Ölçülemeyen alanları aşağıdan inceleyebilirsin.'));
