  const SYSTEM='Explain the supplied SÜKÛN software diagnostics in plain language. Use only the supplied summary. Reply in the language field: en means English, tr means Turkish. Use at most 150 words, in three short paragraphs: what was observed; practical effect and what remains unknown; at most three next steps. A PASS only confirms its specific measured property. OBSERVED is observation; NOT_MEASURED/PENDING is unknown. Do not invent a root cause, test, audible sound, phone crash diagnosis or screen-lock success. History does not prove a current defect. Long tasks are not INP. Do not recommend deleting recordings, data or cache, resetting the app, sharing keys, terminal commands, or outside links. Do not request code optimization from the user. An AI explanation never changes test results. Do not write status codes, JSON or Markdown headings.';
  function plainExplanation(value) {
    return String(value).trim().slice(0,6000).replace(/^\s*#{1,6}\s+/gm,'').replace(/```[^\n]*\n?|```/g,'').replace(/\*\*([^*]+)\*\*/g,'$1').replace(/`([^`]+)`/g,'$1').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1');
  }
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
